const { chromium } = require('playwright');
(async () => {
  const b = await chromium.launch({ executablePath: '/opt/pw-browsers/chromium' }).catch(async()=>await chromium.launch());
  for (const [w,scheme] of [[400,'light'],[400,'dark']]) {
    const p = await b.newPage({ viewport: { width: w, height: 900 }, colorScheme: scheme });
    await p.goto('file://' + process.cwd() + '/page.html');
    const o = await p.evaluate(() => [document.documentElement.scrollWidth, document.documentElement.clientWidth]);
    console.log(w, scheme, 'scroll/client', o);
    await p.screenshot({ path: `shot-${scheme}.png` });
  }
  await b.close();
})();

