(async () => {
  const b = await chromium.launch({ executablePath: '/opt/pw-browsers/chromium' }).catch(async()=>await chromium.launch());
  const p = await b.newPage({ viewport: { width: 400, height: 900 }, colorScheme: 'dark' });
  await p.goto('file://' + process.cwd() + '/page.html');
  const o = await p.evaluate(() => [document.documentElement.scrollWidth, document.documentElement.clientWidth]);
  console.log('scroll/client', o);
  const el = await p.$('#h-test');
  await el.scrollIntoViewIfNeeded();
  await p.evaluate(() => document.getElementById('h-test').scrollIntoView());
  await p.screenshot({ path: 'shot-test.png' });
  await b.close();
})();
EOF
